const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={user:null,trips:[],stops:[],drivers:[],trip:null,tab:'passengers',selectedSeat:null};
const money=(n,currency='DKK')=>new Intl.NumberFormat('da-DK',{style:'currency',currency,maximumFractionDigits:2}).format(n||0);
const date=d=>new Intl.DateTimeFormat('da-DK',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(d));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(url,options={}){const r=await fetch(url,{headers:{'Content-Type':'application/json'},...options});const d=await r.json();if(!r.ok)throw Error(d.error||'Der opstod en fejl');return d}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2500)}
function roleUi(){const admin=state.user.role==='admin';$$('.admin-only').forEach(x=>x.hidden=!admin);$('#userName').textContent=state.user.name;$('#userRole').textContent=admin?'Administrator':'Chauffør';$('#avatar').textContent=state.user.name.split(' ').map(x=>x[0]).slice(0,2).join('')}
async function bootstrap(){const d=await api('/api/bootstrap');Object.assign(state,d);$('#login').hidden=true;$('#app').hidden=false;roleUi();renderDashboard()}
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();try{const f=new FormData(e.target);await api('/api/login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});await bootstrap()}catch(e){toast(e.message)}});
$('#logout').onclick=async()=>{await api('/api/logout',{method:'POST'});location.reload()};
function setTitle(title,eyebrow='BUSOPS'){ $('#pageTitle').textContent=title;$('#eyebrow').textContent=eyebrow }
function activate(name){$$('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===name))}
function tripRows(trips){if(!trips.length)return'<div class="empty">Ingen ture fundet</div>';return `<div class="trips">${trips.map(t=>{const d=new Date(t.departureAt);return`<div class="trip-row" data-trip="${t.id}"><div class="date-box"><strong>${d.getDate()}</strong><small>${d.toLocaleString('da-DK',{month:'short'})}</small></div><div><h3>${esc(t.title)}</h3><p>${date(t.departureAt)} · ${esc(t.origin?.name)} → ${esc(t.destination?.name)}</p></div><div><small>Primær chauffør</small><h3>${esc(t.primaryDriver||'Ikke valgt')}</h3></div><div class="metric"><strong>${t.counts.passengers}</strong><small>Passagerer</small></div><div class="metric"><strong>${t.counts.checkedIn}/${t.counts.passengers}</strong><small>Check-in</small></div><div><span class="pill">Planlagt</span></div><b>›</b></div>`}).join('')}</div>`}
function wireTrips(){$$('[data-trip]').forEach(x=>x.onclick=()=>openTrip(Number(x.dataset.trip)))}
function renderDashboard(){state.trip=null;activate('dashboard');setTitle(state.user.role==='admin'?'Overblik':'Mine ture');const upcoming=state.trips.filter(t=>new Date(t.departureAt)>new Date()).sort((a,b)=>new Date(a.departureAt)-new Date(b.departureAt));const total=state.trips.reduce((n,t)=>n+t.counts.passengers,0),checked=state.trips.reduce((n,t)=>n+t.counts.checkedIn,0),bags=state.trips.reduce((n,t)=>n+t.counts.baggage,0);$('#view').innerHTML=`<div class="stats"><div class="stat"><small>Kommende ture</small><strong>${upcoming.length}</strong></div><div class="stat"><small>Bookede passagerer</small><strong>${total}</strong></div><div class="stat"><small>Checket ind</small><strong>${checked}</strong></div><div class="stat"><small>Sendt bagage</small><strong>${bags}</strong></div></div><section class="panel"><div class="panel-head"><h2>Næste afgange</h2><small>${upcoming.length} planlagte</small></div>${tripRows(upcoming)}</section>`;wireTrips()}
function renderCalendar(){activate('calendar');setTitle('Turkalender');const now=new Date(),first=new Date(now.getFullYear(),now.getMonth(),1),start=new Date(first);start.setDate(1-((first.getDay()+6)%7));let cells='';for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const trips=state.trips.filter(t=>new Date(t.departureAt).toDateString()===d.toDateString());cells+=`<div class="cal-day ${d.getMonth()!==now.getMonth()?'muted':''}"><strong>${d.getDate()}</strong>${trips.map(t=>`<div class="cal-trip" data-trip="${t.id}">${new Date(t.departureAt).toLocaleTimeString('da-DK',{hour:'2-digit',minute:'2-digit'})} ${esc(t.title)}</div>`).join('')}</div>`}$('#view').innerHTML=`<section class="panel"><div class="panel-head"><h2>${now.toLocaleString('da-DK',{month:'long',year:'numeric'})}</h2><small>Man · Tir · Ons · Tor · Fre · Lør · Søn</small></div><div class="calendar">${cells}</div></section>`;wireTrips()}
function renderStops(){activate('stops');setTitle('Opsamlingssteder');$('#view').innerHTML=`<div class="grid2"><section class="panel"><div class="panel-head"><h2>Alle steder</h2><small>${state.stops.length} steder</small></div>${state.stops.map(s=>`<div class="stop-card"><div><strong>${esc(s.name)}</strong><div class="muted">${esc(s.address)}</div></div><span>⌖</span></div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>Tilføj sted</h2></div><form class="form" id="stopForm" style="padding:22px;display:grid"><label>Navn<input name="name" required placeholder="Fx Kolding"></label><label>Adresse<input name="address" placeholder="Adresse eller holdeplads"></label><button class="primary">Tilføj</button></form></section></div>`;$('#stopForm').onsubmit=async e=>{e.preventDefault();try{const s=await api('/api/stops',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});state.stops.push(s);toast('Stedet er oprettet');renderStops()}catch(e){toast(e.message)}}}
const driverNav=document.createElement('button');driverNav.className='nav admin-only';driverNav.dataset.view='drivers';driverNav.innerHTML='♙ <span>Chauffører</span>';document.querySelector('[data-view="stops"]').after(driverNav);
const busNav=document.createElement('button');busNav.className='nav admin-only';busNav.dataset.view='buses';busNav.innerHTML='▰ <span>Busser</span>';document.querySelector('[data-view="stops"]').after(busNav);
const reportNav=document.createElement('button');reportNav.className='nav admin-only';reportNav.dataset.view='reports';reportNav.innerHTML='◫ <span>Salg & økonomi</span>';driverNav.after(reportNav);
$$('.nav').forEach(n=>n.onclick=()=>({dashboard:renderDashboard,calendar:renderCalendar,stops:renderStops,buses:renderBuses,drivers:renderDrivers,reports:renderReports}[n.dataset.view]()))
$('#newTrip').onclick=()=>{const node=$('#tripForm').content.cloneNode(true);$('#modalBody').replaceChildren(node);const form=$('#createTrip');const stopOptions=state.stops.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join(''),driverOptions=state.drivers.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('');form.originId.innerHTML=stopOptions;form.destinationId.innerHTML=stopOptions;form.primaryDriverId.innerHTML=driverOptions;form.secondaryDriverId.insertAdjacentHTML('beforeend',driverOptions);form.onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(form));const t=await api('/api/trips',{method:'POST',body:JSON.stringify(data)});state.trips.push(t);$('#modal').close();toast('Turen er oprettet');renderCalendar()}catch(e){toast(e.message)}};$('#modal').showModal()};
async function openTrip(id){try{state.trip=await api(`/api/trips/${id}`);state.tab=state.user.role==='driver'?'checkin':'passengers';state.selectedSeat=null;state.currentCheckinStop=null;renderTrip()}catch(e){toast(e.message)}}
function renderTrip(){const {trip,passengers,baggage}=state.trip;setTitle(trip.title,'TURDETALJER');activate('');$('#view').innerHTML=`<button class="back" id="back">← Tilbage til ture</button><section class="detail-hero"><div><small>${date(trip.departureAt)}</small><h2>${esc(trip.origin.name)} → ${esc(trip.destination.name)}</h2><p>Primær: ${esc(trip.primaryDriver)}${trip.secondaryDriver?' · Sekundær: '+esc(trip.secondaryDriver):''}</p></div><span class="pill">Planlagt</span></section><div class="stats"><div class="stat"><small>Passagerer</small><strong>${passengers.length}</strong></div><div class="stat"><small>Checket ind</small><strong>${passengers.filter(p=>p.checkedIn).length}</strong></div><div class="stat"><small>Ledige sæder</small><strong>${40-passengers.length}</strong></div><div class="stat"><small>Bagage</small><strong>${baggage.length}</strong></div></div><div class="tabs"><button class="tab ${state.tab==='passengers'?'active':''}" data-tab="passengers">Passagerer</button><button class="tab ${state.tab==='seats'?'active':''}" data-tab="seats">Sædeplan</button><button class="tab ${state.tab==='baggage'?'active':''}" data-tab="baggage">Bagage</button></div><div id="tabContent"></div>`;$('#back').onclick=renderDashboard;$$('[data-tab]').forEach(x=>x.onclick=()=>{state.tab=x.dataset.tab;renderTrip()});renderTab()}
function stopName(id){return state.stops.find(s=>s.id===id)?.name||'–'}
function renderTab(){const el=$('#tabContent'),admin=state.user.role==='admin';if(state.tab==='passengers'){el.innerHTML=`<div class="grid2"><section class="panel"><div class="panel-head"><h2>Passagerliste</h2><small>${state.trip.passengers.length} passagerer</small></div>${state.trip.passengers.length?`<table class="list"><thead><tr><th>Passager</th><th>Rute</th><th>Sæde</th><th>Betaling</th><th>Check-in</th></tr></thead><tbody>${state.trip.passengers.map(p=>`<tr><td><strong>${esc(p.name)}</strong><br><small>${esc(p.phone)}</small></td><td>${esc(stopName(p.pickupStopId))} → ${esc(stopName(p.destinationStopId))}</td><td>${p.seatNumber}</td><td>${p.paymentStatus==='cash'?money(p.cashAmount):'Ikke betalt'}</td><td><button class="mini ${p.checkedIn?'done':''}" data-check="${p.id}">${p.checkedIn?'✓ Inde':'Check ind'}</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Ingen passagerer endnu</div>'}</section>${admin?passengerForm():seatSummary()}</div>`;$$('[data-check]').forEach(b=>b.onclick=()=>toggleCheck(Number(b.dataset.check)));if(admin)wirePassengerForm()}else if(state.tab==='seats'){el.innerHTML=`<section class="panel"><div class="panel-head"><h2>Sædeplan</h2><small>40 sæder</small></div>${seatGrid(false)}</section>`}else{el.innerHTML=`<div class="grid2"><section class="panel"><div class="panel-head"><h2>Bagageliste</h2><small>${state.trip.baggage.length} forsendelser</small></div>${state.trip.baggage.length?`<table class="list"><thead><tr><th>Afsender</th><th>Rute</th><th>Kolli</th><th>Status</th></tr></thead><tbody>${state.trip.baggage.map(b=>`<tr><td><strong>${esc(b.senderName)}</strong><br><small>${esc(b.description)}</small></td><td>${esc(stopName(b.pickupStopId))} → ${esc(stopName(b.destinationStopId))}</td><td>${b.pieces}</td><td><select class="bag-status" data-bag="${b.id}">${[['registered','Registreret'],['received','Modtaget'],['onboard','Ombord'],['delivered','Udleveret'],['unclaimed','Ikke afhentet']].map(([v,l])=>`<option value="${v}" ${b.status===v?'selected':''}>${l}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Ingen sendt bagage</div>'}</section>${admin?baggageForm():'<section class="panel"><div class="empty">Du kan opdatere status direkte i listen.</div></section>'}</div>`;$$('.bag-status').forEach(s=>s.onchange=()=>bagStatus(Number(s.dataset.bag),s.value));if(admin)wireBaggageForm()}}
function seatGrid(selectable=true){let cells='';state.trip.seats.forEach((s,i)=>{if(i%4===2)cells+='<span></span>';cells+=`<button type="button" class="seat ${s.type} ${s.passengerId?'taken':''} ${state.selectedSeat===s.number?'selected':''}" ${s.passengerId||!selectable?'disabled':''} data-seat="${s.number}" title="Sæde ${s.number} · +${s.surcharge} kr.">${s.number}</button>`});return`<div class="seat-map">${cells}</div><div class="legend"><span><i class="dot"></i>Standard</span><span><i class="dot front"></i>Front +100 kr.</span><span><i class="dot table"></i>Bord +75 kr.</span></div>`}
function passengerForm(){return`<section class="panel"><div class="panel-head"><h2>Ny passager</h2></div><form class="form" id="passengerForm" style="padding:20px"><label>Navn<input name="name" required></label><label>Telefon<input name="phone" required></label><label>Fra<select name="pickupStopId">${stopOptions()}</select></label><label>Til<select name="destinationStopId">${stopOptions()}</select></label><label>Betaling<select name="paymentStatus"><option value="unpaid">Ikke betalt</option><option value="cash">Betalt kontant</option></select></label><label>Valuta<select name="paymentCurrency"><option value="DKK">DKK – Danske kroner</option><option value="EUR">EUR – Euro</option></select></label><label>Kontant beløb<input name="cashAmount" type="number" min="0" step="0.01" value="0"></label><div class="wide"><strong>Vælg sæde</strong>${seatGrid(true)}<input type="hidden" name="seatNumber"></div><button class="primary wide">Opret passager</button></form></section>`}
function seatSummary(){return`<section class="panel"><div class="panel-head"><h2>Sædefordeling</h2></div>${seatGrid(false)}</section>`}
function stopOptions(){return state.stops.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}
function wirePassengerForm(){const form=$('#passengerForm');$$('[data-seat]').forEach(b=>b.onclick=()=>{state.selectedSeat=Number(b.dataset.seat);form.seatNumber.value=state.selectedSeat;$$('[data-seat]').forEach(x=>x.classList.toggle('selected',Number(x.dataset.seat)===state.selectedSeat))});form.onsubmit=async e=>{e.preventDefault();if(!form.seatNumber.value)return toast('Vælg et sæde');try{const p=await api(`/api/trips/${state.trip.trip.id}/passengers`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});state.trip.passengers.push(p);state.trip.seats.find(s=>s.number===p.seatNumber).passengerId=p.id;toast('Passageren er oprettet');renderTrip()}catch(e){toast(e.message)}}}
function baggageForm(){return`<section class="panel"><div class="panel-head"><h2>Registrer bagage</h2></div><form class="form" id="baggageForm" style="padding:20px"><label>Afsender<input name="senderName" required></label><label>Telefon<input name="phone" required></label><label>Fra<select name="pickupStopId">${stopOptions()}</select></label><label>Til<select name="destinationStopId">${stopOptions()}</select></label><label>Antal kolli<input name="pieces" type="number" min="1" value="1" required></label><label>Beskrivelse<input name="description" placeholder="Kuffert, pakke …"></label><label>Betaling<select name="paymentStatus"><option value="unpaid">Ikke betalt</option><option value="cash">Betalt kontant</option></select></label><label>Valuta<select name="paymentCurrency"><option value="DKK">DKK – Danske kroner</option><option value="EUR">EUR – Euro</option></select></label><label>Kontant beløb<input name="cashAmount" type="number" min="0" step="0.01" value="0"></label><label class="wide">Bemærkning<textarea name="notes"></textarea></label><button class="primary wide">Registrer bagage</button></form></section>`}
function wireBaggageForm(){const form=$('#baggageForm');form.onsubmit=async e=>{e.preventDefault();try{const b=await api(`/api/trips/${state.trip.trip.id}/baggage`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});state.trip.baggage.push(b);toast('Bagagen er registreret');renderTrip()}catch(e){toast(e.message)}}}
async function toggleCheck(id){const p=state.trip.passengers.find(x=>x.id===id);try{const updated=await api(`/api/trips/${state.trip.trip.id}/passengers`,{method:'PATCH',body:JSON.stringify({id,checkedIn:!p.checkedIn})});Object.assign(p,updated);renderTrip()}catch(e){toast(e.message)}}
async function bagStatus(id,status){try{const b=await api(`/api/trips/${state.trip.trip.id}/baggage`,{method:'PATCH',body:JSON.stringify({id,status})});Object.assign(state.trip.baggage.find(x=>x.id===id),b);toast('Status er opdateret')}catch(e){toast(e.message)}}
bootstrap().catch(()=>{});

// Administratorfunktioner til buskapacitet og vedligeholdelse af opsamlingssteder.
const originalNewTrip = $('#newTrip').onclick;
$('#newTrip').onclick = () => {
  originalNewTrip();
  const form = $('#createTrip');
  form.basePrice.closest('label').insertAdjacentHTML('afterend',`<label>Bus<select name="busId" required><option value="">Vælg bus</option>${(state.buses||[]).map(bus=>`<option value="${bus.id}">${esc(bus.name)} · ${esc(bus.registration)} · ${bus.seatCount} sæder</option>`).join('')}</select><small>Busser oprettes separat i busregisteret</small></label>`);
};

const originalRenderTrip = renderTrip;
renderTrip = function () {
  originalRenderTrip();
  const { trip, passengers } = state.trip;
  const statValues = $$('.stat strong');
  if (statValues[2]) statValues[2].textContent = trip.seatCount - passengers.length;
  const seatHeading = state.tab === 'seats' ? $('.panel-head small') : null;
  if (seatHeading) seatHeading.textContent = `${trip.seatCount} sæder`;
  if (trip.bus) {
    $('.detail-hero p').insertAdjacentHTML('beforeend',`<br>Bus: ${esc(trip.bus.name)} · ${esc(trip.bus.registration)} · ${trip.bus.seatCount} sæder`);
  } else if (state.user.role === 'admin') {
    $('.detail-hero').insertAdjacentHTML('beforeend',`<form id="capacityForm" class="capacity-form"><label>Antal sæder<input name="seatCount" type="number" min="1" max="84" value="${trip.seatCount}" required></label><button>Gem kapacitet</button><small>Maks. 84 sæder</small></form>`);
    $('#capacityForm').onsubmit = async e => {
      e.preventDefault();
      try {
        const updated = await api(`/api/trips/${trip.id}`,{method:'PATCH',body:JSON.stringify({seatCount:Number(e.target.seatCount.value)})});
        state.trip.trip = updated;
        state.trip.seats = await api(`/api/trips/${trip.id}/seats`);
        const overview = state.trips.find(t => t.id === trip.id); if (overview) Object.assign(overview,updated);
        toast('Antal sæder er opdateret'); renderTrip();
      } catch (error) { toast(error.message); }
    };
  }
};

renderStops = function () {
  activate('stops'); setTitle('Opsamlingssteder');
  $('#view').innerHTML=`<div class="grid2"><section class="panel"><div class="panel-head"><h2>Alle steder</h2><small>${state.stops.length} steder</small></div>${state.stops.map(s=>`<div class="stop-card"><div><strong>${esc(s.name)}</strong><div class="muted">${esc(s.address)}</div></div><div class="stop-actions"><button class="mini" data-edit-stop="${s.id}">Rediger</button><button class="mini danger" data-delete-stop="${s.id}">Slet</button></div></div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>Tilføj sted</h2></div><form class="form" id="stopForm" style="padding:22px;display:grid"><label>Navn<input name="name" required placeholder="Fx Kolding"></label><label>Adresse<input name="address" placeholder="Adresse eller holdeplads"></label><button class="primary">Tilføj</button></form></section></div>`;
  $('#stopForm').onsubmit=async e=>{e.preventDefault();try{const s=await api('/api/stops',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});state.stops.push(s);toast('Stedet er oprettet');renderStops()}catch(error){toast(error.message)}};
  $$('[data-edit-stop]').forEach(button=>button.onclick=async()=>{
    const stop=state.stops.find(s=>s.id===Number(button.dataset.editStop));
    const name=prompt('Navn på opsamlingssted',stop.name); if(name===null)return;
    const address=prompt('Adresse',stop.address); if(address===null)return;
    try{const updated=await api(`/api/stops/${stop.id}`,{method:'PATCH',body:JSON.stringify({name,address})});Object.assign(stop,updated);toast('Stedet er opdateret');renderStops()}catch(error){toast(error.message)}
  });
  $$('[data-delete-stop]').forEach(button=>button.onclick=async()=>{
    const stop=state.stops.find(s=>s.id===Number(button.dataset.deleteStop));
    if(!confirm(`Vil du slette ${stop.name}?`))return;
    try{await api(`/api/stops/${stop.id}`,{method:'DELETE'});state.stops=state.stops.filter(s=>s.id!==stop.id);toast('Stedet er slettet');renderStops()}catch(error){toast(error.message)}
  });
};

function renderDrivers() {
  activate('drivers'); setTitle('Chauffører');
  $('#view').innerHTML=`<div class="grid2"><section class="panel"><div class="panel-head"><h2>Chauffører i systemet</h2><small>${state.drivers.length} chauffører</small></div>${state.drivers.length?state.drivers.map(driver=>`<div class="stop-card"><div class="driver-profile"><span class="avatar">${esc(driver.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div><strong>${esc(driver.name)}</strong><div class="muted">${esc(driver.email)}</div></div></div><span class="pill">Chauffør</span></div>`).join(''):'<div class="empty">Ingen chauffører er oprettet</div>'}</section><section class="panel"><div class="panel-head"><h2>Tilføj chauffør</h2></div><form class="form" id="driverForm" style="padding:22px;display:grid"><label>Fulde navn<input name="name" required placeholder="Chaufførens navn"></label><label>E-mail<input name="email" type="email" required placeholder="navn@albaturist.dk"></label><label>Midlertidig adgangskode<input name="password" type="password" minlength="8" required autocomplete="new-password"><small>Mindst 8 tegn</small></label><button class="primary">Opret chauffør</button></form></section></div>`;
  $('#driverForm').onsubmit=async event=>{
    event.preventDefault();
    try {
      const driver=await api('/api/drivers',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});
      state.drivers.push(driver); event.target.reset(); toast('Chaufføren er oprettet'); renderDrivers();
    } catch(error) { toast(error.message); }
  };
}

const originalRenderTabWithCurrency = renderTab;
renderTab = function () {
  originalRenderTabWithCurrency();
  if (state.tab === 'passengers') {
    $$('#tabContent tbody tr').forEach((row,index) => {
      const passenger = state.trip.passengers[index];
      if (passenger?.paymentStatus === 'cash' && row.cells[3]) row.cells[3].textContent = money(passenger.cashAmount,passenger.paymentCurrency || 'DKK');
    });
  }
  if (state.tab === 'baggage') {
    $$('#tabContent tbody tr').forEach((row,index) => {
      const baggage = state.trip.baggage[index]; if (!baggage) return;
      const payment = baggage.paymentStatus === 'cash' ? money(baggage.cashAmount,baggage.paymentCurrency || 'DKK') : 'Ikke betalt';
      row.cells[0]?.insertAdjacentHTML('beforeend',`<br><small class="payment-note">${esc(payment)}</small>`);
    });
  }
};

renderDrivers = function () {
  activate('drivers'); setTitle('Chauffører');
  $('#view').innerHTML=`<div class="grid2"><section class="panel"><div class="panel-head"><h2>Chauffører i systemet</h2><small>${state.drivers.length} chauffører</small></div>${state.drivers.length?state.drivers.map(driver=>`<div class="stop-card"><div class="driver-profile"><span class="avatar">${esc(driver.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div><strong>${esc(driver.name)}</strong><div class="muted">${esc(driver.email)}</div></div></div><div class="stop-actions"><button class="mini" data-edit-driver="${driver.id}">Rediger</button><button class="mini danger" data-delete-driver="${driver.id}">Slet</button></div></div>`).join(''):'<div class="empty">Ingen chauffører er oprettet</div>'}</section><section class="panel"><div class="panel-head"><h2>Tilføj chauffør</h2></div><form class="form" id="driverForm" style="padding:22px;display:grid"><label>Fulde navn<input name="name" required placeholder="Chaufførens navn"></label><label>E-mail<input name="email" type="email" required placeholder="navn@albaturist.dk"></label><label>Midlertidig adgangskode<input name="password" type="password" minlength="8" required autocomplete="new-password"><small>Mindst 8 tegn</small></label><button class="primary">Opret chauffør</button></form></section></div>`;
  $('#driverForm').onsubmit=async event=>{event.preventDefault();try{const driver=await api('/api/drivers',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});state.drivers.push(driver);toast('Chaufføren er oprettet');renderDrivers()}catch(error){toast(error.message)}};
  $$('[data-edit-driver]').forEach(button=>button.onclick=()=>openDriverEditor(Number(button.dataset.editDriver)));
  $$('[data-delete-driver]').forEach(button=>button.onclick=async()=>{
    const driver=state.drivers.find(d=>d.id===Number(button.dataset.deleteDriver));
    if(!confirm(`Vil du slette chaufføren ${driver.name}?`))return;
    try{await api(`/api/drivers/${driver.id}`,{method:'DELETE'});state.drivers=state.drivers.filter(d=>d.id!==driver.id);toast('Chaufføren er slettet');renderDrivers()}catch(error){toast(error.message)}
  });
};

function openDriverEditor(id) {
  const driver=state.drivers.find(d=>d.id===id);
  $('#modalBody').innerHTML=`<h2>Rediger chauffør</h2><p class="muted">Opdater kontaktoplysninger eller angiv en ny adgangskode.</p><form class="form" id="editDriverForm"><label class="wide">Fulde navn<input name="name" value="${esc(driver.name)}" required></label><label class="wide">E-mail<input name="email" type="email" value="${esc(driver.email)}" required></label><label class="wide">Ny adgangskode<input name="password" type="password" minlength="8" autocomplete="new-password" placeholder="Lad feltet være tomt for at beholde den nuværende"><small>Valgfrit · mindst 8 tegn</small></label><button class="primary wide">Gem ændringer</button></form>`;
  $('#editDriverForm').onsubmit=async event=>{event.preventDefault();try{const updated=await api(`/api/drivers/${driver.id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});Object.assign(driver,updated);state.trips.forEach(t=>{if(t.primaryDriverId===driver.id)t.primaryDriver=driver.name;if(t.secondaryDriverId===driver.id)t.secondaryDriver=driver.name});$('#modal').close();toast('Chaufføren er opdateret');renderDrivers()}catch(error){toast(error.message)}};
  $('#modal').showModal();
}

async function renderReports() {
  activate('reports'); setTitle('Salg og økonomi','ADMINISTRATOR');
  $('#view').innerHTML='<section class="panel"><div class="empty">Henter salgstal …</div></section>';
  try {
    const report=await api('/api/reports'); const s=report.summary;
    $('#view').innerHTML=`<div class="finance-grid"><div class="stat finance-main"><small>Solgte billetter</small><strong>${s.tickets}</strong><span>${s.paidTickets} betalt · ${s.unpaidTickets} ikke betalt</span></div><div class="stat"><small>Billetindtægt · DKK</small><strong>${money(s.ticketRevenue.DKK,'DKK')}</strong></div><div class="stat"><small>Billetindtægt · EUR</small><strong>${money(s.ticketRevenue.EUR,'EUR')}</strong></div><div class="stat finance-main"><small>Bagageforsendelser</small><strong>${s.baggage}</strong><span>${s.paidBaggage} betalt · ${s.unpaidBaggage} ikke betalt</span></div><div class="stat"><small>Bagageindtægt · DKK</small><strong>${money(s.baggageRevenue.DKK,'DKK')}</strong></div><div class="stat"><small>Bagageindtægt · EUR</small><strong>${money(s.baggageRevenue.EUR,'EUR')}</strong></div></div><section class="panel report-section"><div class="panel-head"><h2>Solgte billetter</h2><small>${report.tickets.length} registreringer</small></div>${report.tickets.length?`<div class="table-scroll"><table class="list"><thead><tr><th>Passager</th><th>Tur</th><th>Afgang</th><th>Sæde</th><th>Status</th><th>Beløb</th></tr></thead><tbody>${report.tickets.map(ticket=>`<tr><td><strong>${esc(ticket.name)}</strong><br><small>${esc(ticket.phone)}</small></td><td>${esc(ticket.tripTitle)}</td><td>${ticket.departureAt?date(ticket.departureAt):'–'}</td><td>${ticket.seatNumber}</td><td><span class="payment-status ${ticket.paymentStatus==='cash'?'paid':'unpaid'}">${ticket.paymentStatus==='cash'?'Betalt':'Ikke betalt'}</span></td><td><strong>${ticket.paymentStatus==='cash'?money(ticket.cashAmount,ticket.paymentCurrency||'DKK'):'–'}</strong></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Der er endnu ikke solgt billetter</div>'}</section><section class="panel report-section"><div class="panel-head"><h2>Bagagesalg</h2><small>${report.baggage.length} registreringer</small></div>${report.baggage.length?`<div class="table-scroll"><table class="list"><thead><tr><th>Afsender</th><th>Tur</th><th>Afgang</th><th>Kolli</th><th>Status</th><th>Beløb</th></tr></thead><tbody>${report.baggage.map(item=>`<tr><td><strong>${esc(item.senderName)}</strong><br><small>${esc(item.description)}</small></td><td>${esc(item.tripTitle)}</td><td>${item.departureAt?date(item.departureAt):'–'}</td><td>${item.pieces}</td><td><span class="payment-status ${item.paymentStatus==='cash'?'paid':'unpaid'}">${item.paymentStatus==='cash'?'Betalt':'Ikke betalt'}</span></td><td><strong>${item.paymentStatus==='cash'?money(item.cashAmount,item.paymentCurrency||'DKK'):'–'}</strong></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Der er endnu ikke registreret bagagesalg</div>'}</section><p class="report-note">Indtægter vises separat i DKK og EUR. Beløbene omregnes ikke automatisk.</p>`;
  } catch(error) { toast(error.message); renderDashboard(); }
}

const originalRenderTabWithPaymentActions = renderTab;
renderTab = function () {
  originalRenderTabWithPaymentActions();
  if (state.tab === 'passengers') {
    $$('#tabContent tbody tr').forEach((row,index) => {
      const passenger=state.trip.passengers[index];
      if (passenger?.paymentStatus !== 'cash' && row.cells[3]) row.cells[3].innerHTML=`<button class="mini payment-action" data-pay-passenger="${passenger.id}">Registrer betaling</button>`;
    });
    $$('[data-pay-passenger]').forEach(button=>button.onclick=()=>openPaymentDialog('passenger',Number(button.dataset.payPassenger)));
  }
  if (state.tab === 'baggage') {
    $$('#tabContent tbody tr').forEach((row,index) => {
      const item=state.trip.baggage[index];
      if (item?.paymentStatus !== 'cash' && row.cells[0]) row.cells[0].insertAdjacentHTML('beforeend',`<br><button class="mini payment-action" data-pay-baggage="${item.id}">Registrer betaling</button>`);
    });
    $$('[data-pay-baggage]').forEach(button=>button.onclick=()=>openPaymentDialog('baggage',Number(button.dataset.payBaggage)));
  }
};

function openPaymentDialog(kind,id) {
  const isPassenger=kind==='passenger'; const record=(isPassenger?state.trip.passengers:state.trip.baggage).find(item=>item.id===id);
  const title=isPassenger?`Billet · ${record.name}`:`Bagage · ${record.senderName}`;
  const trip=state.trip.trip;const holderField=state.user.role==='admin'?`<label class="wide cash-holder-field">Hvilken chauffør har pengene?<select name="cashHolderUserId"><option value="${trip.primaryDriverId}">${esc(trip.primaryDriver)}</option>${trip.secondaryDriverId?`<option value="${trip.secondaryDriverId}">${esc(trip.secondaryDriver)}</option>`:''}</select></label>`:'';
  $('#modalBody').innerHTML=`<div class="payment-dialog-icon">✓</div><h2>Registrer betaling</h2><p class="muted">${esc(title)} ændres permanent fra ikke betalt til betalt.</p><form class="form" id="paymentForm"><label>Beløb<input name="cashAmount" type="number" min="0.01" step="0.01" required autofocus></label><label>Valuta<select name="paymentCurrency"><option value="DKK">DKK – Danske kroner</option><option value="EUR">EUR – Euro</option></select></label><label class="wide">Betalt hvor?<select name="paymentLocation"><option value="bus">I bussen</option><option value="shop">I salgsbutikken</option></select></label>${holderField}<div class="payment-warning wide">Betalingen kan ikke ændres tilbage til “ikke betalt”.</div><button class="primary wide">Bekræft betaling</button></form>`;
  const locationSelect=$('#paymentForm').paymentLocation;locationSelect.onchange=()=>{const holder=$('.cash-holder-field');if(holder)holder.hidden=locationSelect.value!=='bus'};
  $('#paymentForm').onsubmit=async event=>{event.preventDefault();const payload={id,paymentStatus:'cash',...Object.fromEntries(new FormData(event.target))};try{const updated=await api(`/api/trips/${state.trip.trip.id}/${isPassenger?'passengers':'baggage'}`,{method:'PATCH',body:JSON.stringify(payload)});Object.assign(record,updated);$('#modal').close();toast('Betalingen er registreret');renderTrip()}catch(error){toast(error.message)}};
  $('#modal').showModal();
}

function renderBuses() {
  activate('buses'); setTitle('Busregister'); const buses=state.buses||[];
  $('#view').innerHTML=`<div class="grid2"><section class="panel"><div class="panel-head"><h2>Busser i flåden</h2><small>${buses.length} busser</small></div>${buses.length?buses.map(bus=>`<div class="bus-card"><div class="bus-icon">${bus.type==='double'?'Ⅱ':'Ⅰ'}</div><div class="bus-info"><strong>${esc(bus.name)}</strong><span>${esc(bus.registration)}</span><small>${bus.type==='double'?'Dobbeltdækker':'Almindelig bus'} · ${bus.seatCount} sæder</small></div><div class="stop-actions"><button class="mini" data-edit-bus="${bus.id}">Rediger</button><button class="mini danger" data-delete-bus="${bus.id}">Slet</button></div></div>`).join(''):'<div class="empty">Opret den første bus for at kunne planlægge nye ture</div>'}</section><section class="panel"><div class="panel-head"><h2>Tilføj bus</h2></div><form class="form" id="busForm" style="padding:22px;display:grid"><label>Navn<input name="name" required placeholder="Fx Bus 12"></label><label>Registreringsnummer<input name="registration" required placeholder="AB 12 345"></label><label>Type<select name="type"><option value="standard">Almindelig bus</option><option value="double">Dobbeltdækker</option></select></label><label>Antal sæder<input name="seatCount" type="number" min="1" max="54" value="54" required><small class="capacity-help">Maks. 54 sæder</small></label><button class="primary">Opret bus</button></form></section></div>`;
  const form=$('#busForm');form.seatCount.closest('label').insertAdjacentHTML('afterend','<div class="fixed-deck-layout" hidden><strong>Fast dobbeltdækkerplan</strong><span>Underetage <b>22 sæder</b></span><span>Overetage <b>62 sæder</b></span></div>');form.type.onchange=()=>{const double=form.type.value==='double';form.seatCount.max=double?84:54;form.seatCount.value=double?84:54;form.seatCount.readOnly=double;$('.capacity-help').textContent=double?'Fast kapacitet: 84 sæder':'Maks. 54 sæder';$('.fixed-deck-layout').hidden=!double};
  form.onsubmit=async event=>{event.preventDefault();try{const bus=await api('/api/buses',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});state.buses.push(bus);toast('Bussen er oprettet');renderBuses()}catch(error){toast(error.message)}};
  $$('[data-edit-bus]').forEach(button=>button.onclick=()=>openBusEditor(Number(button.dataset.editBus)));
  $$('[data-delete-bus]').forEach(button=>button.onclick=async()=>{const bus=state.buses.find(b=>b.id===Number(button.dataset.deleteBus));if(!confirm(`Vil du slette ${bus.name}?`))return;try{await api(`/api/buses/${bus.id}`,{method:'DELETE'});state.buses=state.buses.filter(b=>b.id!==bus.id);toast('Bussen er slettet');renderBuses()}catch(error){toast(error.message)}});
}

function openBusEditor(id) {
  const bus=state.buses.find(b=>b.id===id);
  $('#modalBody').innerHTML=`<h2>Rediger bus</h2><p class="muted">Ændringer i kapaciteten gælder også kommende ture med bussen.</p><form class="form" id="editBusForm"><label>Navn<input name="name" value="${esc(bus.name)}" required></label><label>Registreringsnummer<input name="registration" value="${esc(bus.registration)}" required></label><label>Type<select name="type"><option value="standard" ${bus.type==='standard'?'selected':''}>Almindelig bus</option><option value="double" ${bus.type==='double'?'selected':''}>Dobbeltdækker</option></select></label><label>Antal sæder<input name="seatCount" type="number" min="1" max="${bus.type==='double'?84:54}" value="${bus.seatCount}" required></label><button class="primary wide">Gem ændringer</button></form>`;
  const form=$('#editBusForm');form.seatCount.closest('label').insertAdjacentHTML('afterend',`<div class="fixed-deck-layout" ${bus.type==='double'?'':'hidden'}><strong>Fast dobbeltdækkerplan</strong><span>Underetage <b>22 sæder</b></span><span>Overetage <b>62 sæder</b></span></div>`);form.seatCount.readOnly=bus.type==='double';form.type.onchange=()=>{const double=form.type.value==='double';form.seatCount.max=double?84:54;form.seatCount.value=double?84:Math.min(Number(form.seatCount.value)||54,54);form.seatCount.readOnly=double;$('.fixed-deck-layout').hidden=!double};
  form.onsubmit=async event=>{event.preventDefault();try{const updated=await api(`/api/buses/${bus.id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(form)))});Object.assign(bus,updated);state.trips.filter(t=>t.busId===bus.id).forEach(t=>{t.seatCount=bus.seatCount;t.bus={...bus}});$('#modal').close();toast('Bussen er opdateret');renderBuses()}catch(error){toast(error.message)}};
  $('#modal').showModal();
}

seatGrid = function (selectable=true) {
  const seats=state.trip.seats; const isDouble=state.trip.trip.bus?.type==='double'; const decks=isDouble?[['lower','Underetage'],['upper','Overetage']]:[['lower','Sæder']];
  const deckHtml=decks.map(([deck,label])=>{const list=seats.filter(seat=>seat.deck===deck);let cells='';for(let i=0;i<list.length;i+=4){const row=list.slice(i,i+4);row.slice(0,2).forEach(seat=>cells+=seatButton(seat,selectable));cells+='<span class="aisle"></span>';row.slice(2).forEach(seat=>cells+=seatButton(seat,selectable))}return`<section class="bus-deck"><div class="deck-title"><span>${deck==='upper'?'↑':'↓'}</span><strong>${label}</strong><small>${list.length} sæder</small></div><div class="deck-seat-grid">${cells}</div></section>`}).join('');
  return`${deckHtml}<div class="legend"><span><i class="dot"></i>Ledigt</span><span><i class="dot front"></i>Front +100 kr.</span><span><i class="dot table"></i>Bord +75 kr.</span></div>`;
};
function seatButton(seat,selectable){return`<button type="button" class="seat ${seat.type} ${seat.passengerId?'taken':''} ${state.selectedSeat===seat.number?'selected':''}" ${seat.passengerId||!selectable?'disabled':''} data-seat="${seat.number}" title="Sæde ${seat.number} · +${seat.surcharge} kr.">${seat.number}</button>`}

// Orienteringskort: overetagen ligger visuelt over underetagen, begge med 2+2-sæder.
seatGrid = function (selectable=true) {
  const seats=state.trip.seats; const isDouble=state.trip.trip.bus?.type==='double';
  const decks=isDouble?[['upper','Overetage'],['lower','Underetage']]:[['lower','Sædeoversigt']];
  const overview=isDouble?`<div class="deck-orientation"><div class="orientation-bus"><span class="orientation-front">Bussens front</span><div><b>↑ Overetage</b><small>${seats.filter(s=>s.deck==='upper').length} sæder</small></div><i>Trappe</i><div><b>↓ Underetage</b><small>${seats.filter(s=>s.deck==='lower').length} sæder</small></div><span class="orientation-rear">Bagende</span></div><p>Etagerne vises i samme kørselsretning. Venstre og højre sædepar ligger på hver side af midtergangen.</p></div>`:'';
  const deckHtml=decks.map(([deck,label])=>renderDeckMap(deck,label,seats.filter(seat=>seat.deck===deck),selectable,isDouble)).join('');
  return`${overview}<div class="stacked-decks">${deckHtml}</div><div class="legend"><span><i class="dot"></i>Ledigt</span><span><i class="dot front"></i>Front +100 kr.</span><span><i class="dot table"></i>Bord +75 kr.</span><span><i class="dot occupied"></i>Optaget</span></div>`;
};

function renderDeckMap(deck,label,seats,selectable,isDouble) {
  let rows='';
  for(let i=0;i<seats.length;i+=4){const row=seats.slice(i,i+4);rows+=`<div class="seat-row"><div class="seat-pair">${row.slice(0,2).map(seat=>seatButton(seat,selectable)).join('')}</div><span class="aisle"><i>↕</i></span><div class="seat-pair">${row.slice(2,4).map(seat=>seatButton(seat,selectable)).join('')}</div></div>`}
  return`<section class="bus-deck orientation-deck ${deck}"><div class="deck-title"><span>${deck==='upper'?'↑':'↓'}</span><strong>${label}</strong><small>${seats.length} sæder</small></div><div class="bus-outline"><div class="driver-marker">${deck==='lower'?'Rat':'Front'}</div>${isDouble&&deck==='lower'?'<div class="stairs-marker">Trappe</div>':''}<div class="oriented-seat-grid">${rows}</div><div class="rear-marker">Bagende</div></div></section>`;
}

const tripRendererBeforeExpenses = renderTrip;
renderTrip = function () {
  tripRendererBeforeExpenses();
  const tabs=$('.tabs');
  if(tabs){tabs.insertAdjacentHTML('beforeend',`<button class="tab ${state.tab==='expenses'?'active':''}" data-expense-tab>Udgifter <span class="tab-count">${state.trip.expenses?.length||0}</span></button>`);$('[data-expense-tab]').onclick=()=>{state.tab='expenses';renderTrip()}}
  if(state.tab==='expenses'){ $$('.tab').forEach(tab=>tab.classList.remove('active'));$('[data-expense-tab]').classList.add('active');renderExpensesTab(); }
};

const passengerRendererBeforeEnhancements = renderTab;
renderTab = function () {
  passengerRendererBeforeEnhancements();
  if(state.tab==='passengers') renderEnhancedPassengerTab();
};

function renderEnhancedPassengerTab() {
  const el=$('#tabContent'),admin=state.user.role==='admin';
  const passengers=[...state.trip.passengers].sort((a,b)=>stopName(a.pickupStopId).localeCompare(stopName(b.pickupStopId),'da')||a.name.localeCompare(b.name,'da'));
  const stops=[...new Set(passengers.map(p=>p.pickupStopId))];
  const cashCards=tripCashCards();
  el.innerHTML=`${cashCards}<div class="pickup-groups">${stops.map(stopId=>{const group=passengers.filter(p=>p.pickupStopId===stopId);return`<button data-pickup-filter="${stopId}"><strong>${esc(stopName(stopId))}</strong><span>${group.filter(p=>p.checkedIn).length}/${group.length} checket ind</span></button>`}).join('')}</div><div class="passenger-toolbar"><label class="search-box">⌕<input id="passengerSearch" placeholder="Søg navn, telefon eller sæde"></label><select id="attendanceFilter"><option value="">Alle check-in-statusser</option><option value="pending">Afventer</option><option value="checked_in">Checket ind</option><option value="no_show">Udeblevet</option></select><select id="paymentFilter"><option value="">Alle betalinger</option><option value="cash">Betalt</option><option value="unpaid">Ikke betalt</option></select><button class="mini" id="clearPassengerFilters">Nulstil</button></div><div class="grid2 passenger-layout"><section class="panel"><div class="panel-head"><h2>Passagerliste</h2><small id="passengerResultCount">${passengers.length} passagerer</small></div>${passengers.length?`<div class="table-scroll"><table class="list enhanced-passengers"><thead><tr><th>Passager</th><th>Opsamling</th><th>Sæde</th><th>Status</th><th>Betaling</th><th>Handlinger</th></tr></thead><tbody>${passengers.map(p=>passengerRow(p)).join('')}</tbody></table></div>`:'<div class="empty">Ingen passagerer endnu</div>'}</section>${admin?passengerForm():seatSummary()}</div>`;
  $('.passenger-toolbar').insertAdjacentHTML('beforeend','<button class="mini" id="exportPassengers">Eksportér CSV</button><button class="mini" id="printPassengers">Udskriv</button>');
  $('#exportPassengers').onclick=exportPassengerList;$('#printPassengers').onclick=()=>window.print();
  $$('[data-check]').forEach(button=>button.onclick=()=>toggleCheck(Number(button.dataset.check)));
  $$('[data-no-show]').forEach(button=>button.onclick=()=>markNoShow(Number(button.dataset.noShow)));
  $$('[data-pay-passenger]').forEach(button=>button.onclick=()=>openPaymentDialog('passenger',Number(button.dataset.payPassenger)));
  $$('[data-passenger-detail]').forEach(button=>button.onclick=()=>showPassengerDetail(Number(button.dataset.passengerDetail)));
  if(admin)wirePassengerForm();
  const apply=()=>filterPassengerRows();$('#passengerSearch').oninput=apply;$('#attendanceFilter').onchange=apply;$('#paymentFilter').onchange=apply;$('#clearPassengerFilters').onclick=()=>{$('#passengerSearch').value='';$('#attendanceFilter').value='';$('#paymentFilter').value='';$$('[data-passenger-row]').forEach(row=>row.dataset.pickupActive='');apply()};
  $$('[data-pickup-filter]').forEach(button=>button.onclick=()=>{const selected=button.classList.toggle('active');$$('[data-pickup-filter]').filter(x=>x!==button).forEach(x=>x.classList.remove('active'));$$('[data-passenger-row]').forEach(row=>row.dataset.pickupActive=selected?button.dataset.pickupFilter:'');apply()});
}

function passengerRow(p){const status=p.attendanceStatus|| (p.checkedIn?'checked_in':'pending');const statusText={pending:'Afventer',checked_in:'Checket ind',no_show:'Udeblevet'}[status];return`<tr data-passenger-row data-search="${esc(`${p.name} ${p.phone} ${p.seatNumber}`.toLowerCase())}" data-attendance="${status}" data-payment="${p.paymentStatus}" data-pickup="${p.pickupStopId}"><td><strong>${esc(p.name)}</strong><br><a class="phone-link" href="tel:${esc(p.phone)}">${esc(p.phone)}</a></td><td>${esc(stopName(p.pickupStopId))}<br><small>til ${esc(stopName(p.destinationStopId))}</small></td><td><span class="seat-badge">${p.seatNumber}</span></td><td><span class="attendance ${status}">${statusText}</span></td><td>${p.paymentStatus==='cash'?`<span class="payment-status paid">${money(p.cashAmount,p.paymentCurrency||'DKK')}</span>`:`<button class="mini payment-action" data-pay-passenger="${p.id}">Registrer betaling</button>`}</td><td><div class="row-actions"><button class="mini ${p.checkedIn?'done':''}" data-check="${p.id}">${p.checkedIn?'✓ Inde':'Check ind'}</button>${!p.checkedIn&&status!=='no_show'?`<button class="icon-action" data-no-show="${p.id}" title="Markér udeblevet">×</button>`:''}<button class="icon-action" data-passenger-detail="${p.id}" title="Se detaljer">•••</button></div></td></tr>`}
function filterPassengerRows(){const search=$('#passengerSearch').value.toLowerCase(),attendance=$('#attendanceFilter').value,payment=$('#paymentFilter').value;let visible=0;$$('[data-passenger-row]').forEach(row=>{const pickup=row.dataset.pickupActive;const show=(!search||row.dataset.search.includes(search))&&(!attendance||row.dataset.attendance===attendance)&&(!payment||row.dataset.payment===payment)&&(!pickup||row.dataset.pickup===pickup);row.hidden=!show;if(show)visible++});$('#passengerResultCount').textContent=`${visible} passagerer`}
async function markNoShow(id){try{const updated=await api(`/api/trips/${state.trip.trip.id}/passengers`,{method:'PATCH',body:JSON.stringify({id,attendanceStatus:'no_show'})});Object.assign(state.trip.passengers.find(p=>p.id===id),updated);toast('Passageren er markeret som udeblevet');renderTrip()}catch(error){toast(error.message)}}
function tripDriverName(id){const trip=state.trip.trip;if(id===state.user.id)return state.user.name;if(id===trip.primaryDriverId)return trip.primaryDriver;if(id===trip.secondaryDriverId)return trip.secondaryDriver;return state.drivers?.find(d=>d.id===id)?.name||'Ukendt'}
function tripCashCards(){const trip=state.trip.trip;const driverIds=[trip.primaryDriverId,trip.secondaryDriverId].filter(Boolean);return`<div class="cash-custody">${driverIds.map(id=>{const records=[...state.trip.passengers,...state.trip.baggage].filter(r=>r.cashHolderUserId===id);const dkk=records.filter(r=>(r.paymentCurrency||'DKK')==='DKK').reduce((s,r)=>s+Number(r.cashAmount||0),0),eur=records.filter(r=>r.paymentCurrency==='EUR').reduce((s,r)=>s+Number(r.cashAmount||0),0);return`<div><span>Kontanter hos</span><strong>${esc(tripDriverName(id))}</strong><b>${money(dkk,'DKK')} · ${money(eur,'EUR')}</b></div>`}).join('')}</div>`}
function showPassengerDetail(id){const p=state.trip.passengers.find(x=>x.id===id);const status=p.attendanceStatus==='no_show'?'Udeblevet':p.checkedIn?'Checket ind':'Afventer';const holder=p.cashHolderUserId?tripDriverName(p.cashHolderUserId):p.paymentLocation==='shop'?'Salgsbutikken':'–';$('#modalBody').innerHTML=`<h2>${esc(p.name)}</h2><p class="muted">Passagerdetaljer og registreret historik</p><div class="detail-list"><div><span>Telefon</span><strong><a href="tel:${esc(p.phone)}">${esc(p.phone)}</a></strong></div><div><span>Rute</span><strong>${esc(stopName(p.pickupStopId))} → ${esc(stopName(p.destinationStopId))}</strong></div><div><span>Sæde</span><strong>${p.seatNumber} · ${esc(p.seatType)}</strong></div><div><span>Check-in</span><strong>${status}${p.checkedInAt?' · '+date(p.checkedInAt):''}</strong></div><div><span>Betaling</span><strong>${p.paymentStatus==='cash'?money(p.cashAmount,p.paymentCurrency||'DKK'):'Ikke betalt'}</strong></div><div><span>Pengene står hos</span><strong>${esc(holder)}</strong></div></div>`;$('#modal').showModal()}

function renderExpensesTab(){const expenses=state.trip.expenses||[],trip=state.trip.trip;const dkk=expenses.filter(e=>e.currency==='DKK').reduce((s,e)=>s+Number(e.amount),0),eur=expenses.filter(e=>e.currency==='EUR').reduce((s,e)=>s+Number(e.amount),0);$('#tabContent').innerHTML=`<div class="expense-trip-context"><span>Udgifterne bogføres automatisk på</span><strong>${esc(trip.title)}</strong><b>${date(trip.departureAt)}</b><small>Kun turens tildelte chauffører og administratoren kan registrere udgifter.</small></div><div class="expense-summary"><div class="stat"><small>Udgifter i DKK</small><strong>${money(dkk,'DKK')}</strong></div><div class="stat"><small>Udgifter i EUR</small><strong>${money(eur,'EUR')}</strong></div><div class="stat"><small>Kvitteringer</small><strong>${expenses.length}</strong></div></div><div class="grid2"><section class="panel"><div class="panel-head"><h2>Turens udgifter</h2><small>${expenses.length} registreringer</small></div>${expenses.length?`<table class="list"><thead><tr><th>Udgift</th><th>Turens dato</th><th>Beløb</th><th>Kvittering</th></tr></thead><tbody>${expenses.map(e=>`<tr><td><strong>${esc(e.category)}</strong><br><small>${esc(e.description)}${e.createdByName?` · Registreret af ${esc(e.createdByName)}`:''}</small></td><td>${date(e.expenseDate||trip.departureAt)}</td><td><strong>${money(e.amount,e.currency)}</strong></td><td><a class="receipt-link" href="/api/expenses/${e.id}/receipt" target="_blank">Se kvittering ↗</a></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Ingen udgifter er registreret</div>'}</section><section class="panel"><div class="panel-head"><h2>Upload kvittering</h2></div><form class="form" id="expenseForm" style="padding:20px"><label>Kategori<select name="category"><option>Brændstof</option><option>Vejafgift</option><option>Færge</option><option>Parkering</option><option>Reparation</option><option>Andet</option></select></label><label>Beløb<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Valuta<select name="currency"><option value="DKK">DKK</option><option value="EUR">EUR</option></select></label><label>Kvittering<input name="receipt" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" required><small>PDF eller billede · maks. 5 MB</small></label><label class="wide">Beskrivelse<textarea name="description" placeholder="Valgfri bemærkning"></textarea></label><button class="primary wide">Gem på denne tur</button></form></section></div>`;$('#expenseForm').onsubmit=uploadExpense}
async function uploadExpense(event){event.preventDefault();const form=event.target,file=form.receipt.files[0];if(!file||file.size>5*1024*1024)return toast('Kvitteringen må højst fylde 5 MB');try{const receiptData=await fileAsDataUrl(file);const payload={category:form.category.value,amount:form.amount.value,currency:form.currency.value,description:form.description.value,receiptName:file.name,receiptType:file.type,receiptData};const expense=await api(`/api/trips/${state.trip.trip.id}/expenses`,{method:'POST',body:JSON.stringify(payload)});state.trip.expenses.push(expense);toast('Udgiften og kvitteringen er gemt');renderTrip()}catch(error){toast(error.message)}}
function fileAsDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Filen kunne ikke læses'));reader.readAsDataURL(file)})}
function exportPassengerList(){const headings=['Navn','Telefon','Opsamling','Destination','Sæde','Check-in','Betaling','Beløb','Valuta'];const rows=state.trip.passengers.map(p=>[p.name,p.phone,stopName(p.pickupStopId),stopName(p.destinationStopId),p.seatNumber,p.checkedIn?'Checket ind':p.attendanceStatus==='no_show'?'Udeblevet':'Afventer',p.paymentStatus==='cash'?'Betalt':'Ikke betalt',p.cashAmount||0,p.paymentCurrency||'DKK']);const csv=[headings,...rows].map(row=>row.map(value=>`"${String(value).replace(/"/g,'""')}"`).join(';')).join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`passagerliste-${state.trip.trip.id}.csv`;link.click();URL.revokeObjectURL(url)}

const reportRendererBeforeCashCustody = renderReports;
renderReports = async function () {
  await reportRendererBeforeCashCustody(); if(!$('.nav[data-view="reports"]')?.classList.contains('active'))return;
  try{const report=await api('/api/reports');const s=report.summary;const custody=`<section class="panel report-section"><div class="panel-head"><h2>Kontanter hos chaufførerne</h2><small>Betalinger modtaget i bussen</small></div>${s.cashByDriver.length?`<div class="driver-cash-grid">${s.cashByDriver.map(row=>`<div><span>Pengene står hos</span><strong>${esc(row.driverName)}</strong><b>${money(row.amounts.DKK,'DKK')}</b><b>${money(row.amounts.EUR,'EUR')}</b><small>${row.payments} betalinger</small></div>`).join('')}</div>`:'<div class="empty">Ingen kontantbetalinger er registreret i busserne</div>'}</section>`;const expenses=`<section class="panel report-section"><div class="panel-head"><h2>Turudgifter og kvitteringer</h2><small>${report.expenses.length} udgifter</small></div><div class="expense-report-total"><div><span>Udgifter DKK</span><strong>${money(s.expenseTotals.DKK,'DKK')}</strong></div><div><span>Udgifter EUR</span><strong>${money(s.expenseTotals.EUR,'EUR')}</strong></div></div>${report.expenses.length?`<div class="table-scroll"><table class="list"><thead><tr><th>Tur</th><th>Kategori</th><th>Turens dato</th><th>Beløb</th><th>Bilag</th></tr></thead><tbody>${report.expenses.map(e=>`<tr><td>${esc(e.tripTitle)}</td><td>${esc(e.category)}</td><td>${date(e.expenseDate||e.departureAt)}</td><td><strong>${money(e.amount,e.currency)}</strong></td><td><a class="receipt-link" href="/api/expenses/${e.id}/receipt" target="_blank">Se kvittering ↗</a></td></tr>`).join('')}</tbody></table></div>`:''}</section>`;$('#view').insertAdjacentHTML('beforeend',custody+expenses)}catch(error){toast(error.message)}
};

const tripRendererBeforeCheckInMode = renderTrip;
renderTrip = function () {
  tripRendererBeforeCheckInMode();
  const tabs=$('.tabs');
  if(tabs){tabs.insertAdjacentHTML('afterbegin',`<button class="tab ${state.tab==='checkin'?'active':''}" data-checkin-tab>Check-in</button>`);$('[data-checkin-tab]').onclick=()=>{state.tab='checkin';renderTrip()}}
  if(state.tab==='checkin'){ $$('.tab').forEach(tab=>tab.classList.remove('active'));$('[data-checkin-tab]').classList.add('active');renderCheckInMode(); }
};

function renderCheckInMode(){if(navigator.onLine&&offlineQueue().length)syncOfflineCheckIns();const passengers=state.trip.passengers;const stopIds=[...new Set(passengers.map(p=>p.pickupStopId))];if(!state.currentCheckinStop||!stopIds.includes(Number(state.currentCheckinStop)))state.currentCheckinStop=stopIds.find(id=>passengers.some(p=>p.pickupStopId===id&&!p.checkedIn&&p.attendanceStatus!=='no_show'))||stopIds[0];const stopId=Number(state.currentCheckinStop),atStop=passengers.filter(p=>p.pickupStopId===stopId),checked=atStop.filter(p=>p.checkedIn).length,overall=passengers.filter(p=>p.checkedIn).length,problems=atStop.filter(p=>p.paymentStatus!=='cash'||p.attendanceStatus==='no_show');const pct=atStop.length?Math.round(checked/atStop.length*100):0;$('#tabContent').innerHTML=`<div class="connection-banner ${navigator.onLine?'online':'offline'}" id="connectionBanner">${navigator.onLine?'● Online · ændringer gemmes med det samme':'● Offline · check-in gemmes lokalt og synkroniseres senere'}</div><section class="checkin-command"><div><small>AKTUELT OPSAMLINGSSTED</small><select id="checkinStop">${stopIds.map(id=>`<option value="${id}" ${id===stopId?'selected':''}>${esc(stopName(id))}</option>`).join('')}</select></div><div class="checkin-progress"><span><b>${checked}</b> af ${atStop.length} ved stoppestedet</span><div><i style="width:${pct}%"></i></div><small>${overall} af ${passengers.length} på hele turen</small></div><button class="primary" id="completeStop" ${!atStop.length?'disabled':''}>Afslut stoppested →</button></section>${tripCashCards()}<div class="checkin-alerts"><div><strong>${atStop.filter(p=>!p.checkedIn&&p.attendanceStatus!=='no_show').length}</strong><span>Afventer</span></div><div class="warning"><strong>${atStop.filter(p=>p.paymentStatus!=='cash').length}</strong><span>Ikke betalt</span></div><div class="danger"><strong>${atStop.filter(p=>p.attendanceStatus==='no_show').length}</strong><span>Udeblevet</span></div><button id="toggleProblems">Vis ${problems.length} opmærksomhedspunkter</button></div><label class="checkin-search">⌕<input id="checkinSearch" placeholder="Søg passager, telefon eller sæde"></label><div id="problemPanel" class="problem-panel" hidden>${problems.map(p=>`<button data-focus-passenger="${p.id}"><strong>${esc(p.name)}</strong><span>${p.paymentStatus!=='cash'?'Ikke betalt':'Udeblevet'}</span></button>`).join('')||'<p>Ingen problemer ved dette stoppested</p>'}</div><div class="checkin-sections">${checkinSection('Afventer',atStop.filter(p=>!p.checkedIn&&p.attendanceStatus!=='no_show'),'pending')}${checkinSection('Checket ind',atStop.filter(p=>p.checkedIn),'checked')}${checkinSection('Udeblevet',atStop.filter(p=>p.attendanceStatus==='no_show'),'noshow')}</div><div id="undoCheckin"></div>`;wireCheckInMode(stopIds)}
function checkinSection(title,passengers,kind){return`<section class="checkin-group ${kind}"><header><h3>${title}</h3><span>${passengers.length}</span></header><div>${passengers.map(checkinCard).join('')||'<p class="empty-small">Ingen passagerer</p>'}</div></section>`}
function checkinCard(p){return`<article class="checkin-card ${p.checkedIn?'is-checked':''} ${p.attendanceStatus==='no_show'?'is-noshow':''}" data-checkin-card="${p.id}" data-search="${esc(`${p.name} ${p.phone} ${p.seatNumber}`.toLowerCase())}"><div class="checkin-seat"><small>SÆDE</small><strong>${p.seatNumber}</strong></div><div class="checkin-person"><h3>${esc(p.name)}</h3><a href="tel:${esc(p.phone)}">${esc(p.phone)}</a><span>${esc(stopName(p.pickupStopId))} → ${esc(stopName(p.destinationStopId))}</span>${p.pendingSync?'<em>Afventer synkronisering</em>':''}</div><div class="checkin-payment ${p.paymentStatus==='cash'?'paid':'unpaid'}"><small>${p.paymentStatus==='cash'?'BETALT':'IKKE BETALT'}</small><strong>${p.paymentStatus==='cash'?money(p.cashAmount,p.paymentCurrency||'DKK'):'Kræver handling'}</strong></div><div class="checkin-actions">${!p.checkedIn?`<button class="check-button" data-fast-check="${p.id}">✓ Check ind</button>`:'<span class="checked-label">✓ Checket ind</span>'}${p.paymentStatus!=='cash'?`<button class="pay-button" data-pay-passenger="${p.id}">Registrer betaling</button>`:''}<a href="tel:${esc(p.phone)}" class="icon-action" title="Ring">☎</a>${!p.checkedIn&&p.attendanceStatus!=='no_show'?`<button class="icon-action" data-no-show="${p.id}" title="Udeblevet">×</button>`:''}<button class="icon-action" data-passenger-detail="${p.id}" title="Detaljer">•••</button></div></article>`}
function wireCheckInMode(stopIds){$('#checkinStop').onchange=e=>{state.currentCheckinStop=Number(e.target.value);renderTrip()};$('#checkinSearch').oninput=e=>{const value=e.target.value.toLowerCase();$$('[data-checkin-card]').forEach(card=>card.hidden=!card.dataset.search.includes(value))};$('#toggleProblems').onclick=()=>{$('#problemPanel').hidden=!$('#problemPanel').hidden};$$('[data-focus-passenger]').forEach(button=>button.onclick=()=>{const card=$(`[data-checkin-card="${button.dataset.focusPassenger}"]`);if(card){card.scrollIntoView({behavior:'smooth',block:'center'});card.classList.add('focus-pulse');setTimeout(()=>card.classList.remove('focus-pulse'),1500)}});$$('[data-fast-check]').forEach(button=>button.onclick=()=>performFastCheckIn(Number(button.dataset.fastCheck)));$$('[data-pay-passenger]').forEach(button=>button.onclick=()=>openPaymentDialog('passenger',Number(button.dataset.payPassenger)));$$('[data-no-show]').forEach(button=>button.onclick=()=>markNoShow(Number(button.dataset.noShow)));$$('[data-passenger-detail]').forEach(button=>button.onclick=()=>showPassengerDetail(Number(button.dataset.passengerDetail)));$('#completeStop').onclick=()=>{state.completedCheckinStops=state.completedCheckinStops||[];if(!state.completedCheckinStops.includes(state.currentCheckinStop))state.completedCheckinStops.push(state.currentCheckinStop);const index=stopIds.indexOf(Number(state.currentCheckinStop));state.currentCheckinStop=stopIds[index+1]||stopIds[0];toast('Stoppestedet er afsluttet');renderTrip()};showUndoCheckIn()}
async function performFastCheckIn(id){const passenger=state.trip.passengers.find(p=>p.id===id);try{if(!navigator.onLine)throw Error('offline');const updated=await api(`/api/trips/${state.trip.trip.id}/passengers`,{method:'PATCH',body:JSON.stringify({id,checkedIn:true})});Object.assign(passenger,updated);state.lastCheckIn={id,expires:Date.now()+30000,offline:false};signalCheckIn();renderTrip()}catch(error){const offline=!navigator.onLine||/fetch|network|offline|load failed/i.test(error.message);if(!offline)return toast(error.message);passenger.checkedIn=true;passenger.attendanceStatus='checked_in';passenger.checkedInAt=new Date().toISOString();passenger.checkedInBy=state.user.id;passenger.pendingSync=true;queueOfflineCheckIn({tripId:state.trip.trip.id,id,checkedIn:true});state.lastCheckIn={id,expires:Date.now()+30000,offline:true};signalCheckIn();renderTrip()}}
function signalCheckIn(){navigator.vibrate?.(80);try{const audio=new(window.AudioContext||window.webkitAudioContext)(),osc=audio.createOscillator(),gain=audio.createGain();osc.frequency.value=660;gain.gain.value=.05;osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+.09)}catch(_){}}
function showUndoCheckIn(){const item=state.lastCheckIn;if(!item||item.expires<=Date.now()){const target=$('#undoCheckin');if(target)target.innerHTML='';return}const passenger=state.trip.passengers.find(p=>p.id===item.id);if(!passenger)return;const seconds=Math.max(1,Math.ceil((item.expires-Date.now())/1000));$('#undoCheckin').innerHTML=`<div class="undo-bar"><span>✓ ${esc(passenger.name)} er checket ind</span><button id="undoButton">Fortryd (${seconds})</button></div>`;$('#undoButton').onclick=undoLastCheckIn;clearTimeout(state.undoTimer);state.undoTimer=setTimeout(()=>{if(state.tab==='checkin')showUndoCheckIn()},1000)}
async function undoLastCheckIn(){const item=state.lastCheckIn;if(!item||item.expires<Date.now())return toast('Fortrydelsesfristen er udløbet');const passenger=state.trip.passengers.find(p=>p.id===item.id);try{if(item.offline){removeOfflineCheckIn(item.id);Object.assign(passenger,{checkedIn:false,attendanceStatus:'pending',checkedInAt:null,checkedInBy:null,pendingSync:false})}else{const updated=await api(`/api/trips/${state.trip.trip.id}/passengers`,{method:'PATCH',body:JSON.stringify({id:item.id,checkedIn:false})});Object.assign(passenger,updated)}state.lastCheckIn=null;toast('Check-in er fortrudt');renderTrip()}catch(error){toast(error.message)}}
function offlineQueue(){try{return JSON.parse(localStorage.getItem('busops-checkin-queue')||'[]')}catch(_){return[]}}function queueOfflineCheckIn(item){const queue=offlineQueue();queue.push(item);localStorage.setItem('busops-checkin-queue',JSON.stringify(queue))}function removeOfflineCheckIn(id){localStorage.setItem('busops-checkin-queue',JSON.stringify(offlineQueue().filter(item=>item.id!==id)))}
async function syncOfflineCheckIns(){if(!navigator.onLine||state.syncingOffline)return;state.syncingOffline=true;const queue=offlineQueue(),remaining=[];for(const item of queue){try{const updated=await api(`/api/trips/${item.tripId}/passengers`,{method:'PATCH',body:JSON.stringify({id:item.id,checkedIn:item.checkedIn})});if(state.trip?.trip.id===item.tripId){const local=state.trip.passengers.find(p=>p.id===item.id);if(local)Object.assign(local,updated,{pendingSync:false})}}catch(_){remaining.push(item)}}localStorage.setItem('busops-checkin-queue',JSON.stringify(remaining));state.syncingOffline=false;if(queue.length&&!remaining.length)toast('Offline check-in er synkroniseret')}
window.addEventListener('online',()=>{syncOfflineCheckIns();if(state.tab==='checkin')renderTrip()});window.addEventListener('offline',()=>{if(state.tab==='checkin')renderTrip()});syncOfflineCheckIns();

showPassengerDetail = function(id){const p=state.trip.passengers.find(x=>x.id===id),status=p.attendanceStatus==='no_show'?'Udeblevet':p.checkedIn?'Checket ind':'Afventer',holder=p.cashHolderUserId?tripDriverName(p.cashHolderUserId):p.paymentLocation==='shop'?'Salgsbutikken':'–',history=[...(p.attendanceHistory||[])].reverse();$('#modalBody').innerHTML=`<h2>${esc(p.name)}</h2><p class="muted">Passagerdetaljer og check-in-historik</p><div class="detail-list"><div><span>Telefon</span><strong><a href="tel:${esc(p.phone)}">${esc(p.phone)}</a></strong></div><div><span>Rute</span><strong>${esc(stopName(p.pickupStopId))} → ${esc(stopName(p.destinationStopId))}</strong></div><div><span>Sæde</span><strong>${p.seatNumber} · ${esc(p.seatType)}</strong></div><div><span>Check-in</span><strong>${status}${p.checkedInAt?' · '+date(p.checkedInAt):''}</strong></div><div><span>Betaling</span><strong>${p.paymentStatus==='cash'?money(p.cashAmount,p.paymentCurrency||'DKK'):'Ikke betalt'}</strong></div><div><span>Pengene står hos</span><strong>${esc(holder)}</strong></div></div><h3 class="history-title">Hændelser</h3><div class="history-list">${history.length?history.map(event=>`<div><i class="${event.action}"></i><span>${event.action==='checked_in'?'Checket ind':event.action==='no_show'?'Markeret udeblevet':'Check-in fortrudt'}<small>${date(event.at)} · ${esc(tripDriverName(event.userId))}</small></span></div>`).join(''):'<p>Ingen check-in-hændelser endnu</p>'}</div>`;$('#modal').showModal()}

const wireCheckInBeforeStopPersistence=wireCheckInMode;
wireCheckInMode=function(stopIds){wireCheckInBeforeStopPersistence(stopIds);$('#completeStop').onclick=async()=>{const current=Number(state.currentCheckinStop),pending=state.trip.passengers.filter(p=>p.pickupStopId===current&&!p.checkedIn&&p.attendanceStatus!=='no_show').length;if(pending&&!confirm(`${pending} passagerer afventer stadig. Vil du afslutte stoppestedet?`))return;try{const updated=await api(`/api/trips/${state.trip.trip.id}`,{method:'PATCH',body:JSON.stringify({completedStopId:current})});state.trip.trip=updated;const index=stopIds.indexOf(current);state.currentCheckinStop=stopIds[index+1]||stopIds[0];toast('Stoppestedet er afsluttet');renderTrip()}catch(error){toast(error.message)}}};
const wireCheckInBeforeCompletedLabels=wireCheckInMode;wireCheckInMode=function(stopIds){wireCheckInBeforeCompletedLabels(stopIds);const completed=state.trip.trip.completedStopIds||[];[...$('#checkinStop').options].forEach(option=>{if(completed.includes(Number(option.value)))option.textContent=`✓ ${option.textContent}`})};

const tripRendererBeforeSettlements=renderTrip;
renderTrip=function(){tripRendererBeforeSettlements();const tabs=$('.tabs');if(tabs){const pending=(state.trip.settlements||[]).filter(s=>s.status==='pending').length;tabs.insertAdjacentHTML('beforeend',`<button class="tab ${state.tab==='settlements'?'active':''}" data-settlement-tab>Kontantafstemning ${pending?`<span class="tab-count attention">${pending}</span>`:''}</button>`);$('[data-settlement-tab]').onclick=()=>{state.tab='settlements';renderTrip()}}if(state.tab==='settlements'){$$('.tab').forEach(tab=>tab.classList.remove('active'));$('[data-settlement-tab]').classList.add('active');renderSettlementTab()}};

tripCashCards=function(){const trip=state.trip.trip,driverIds=[trip.primaryDriverId,trip.secondaryDriverId].filter(Boolean);return`<div class="cash-custody">${driverIds.map(id=>{const records=[...state.trip.passengers,...state.trip.baggage].filter(r=>r.cashHolderUserId===id&&!r.cashHandedOverAt),dkk=records.filter(r=>(r.paymentCurrency||'DKK')==='DKK').reduce((s,r)=>s+Number(r.cashAmount||0),0),eur=records.filter(r=>r.paymentCurrency==='EUR').reduce((s,r)=>s+Number(r.cashAmount||0),0);return`<div><span>Uafleverede kontanter hos</span><strong>${esc(tripDriverName(id))}</strong><b>${money(dkk,'DKK')} · ${money(eur,'EUR')}</b></div>`}).join('')}</div>`};

function renderSettlementTab(){const trip=state.trip.trip,all=state.trip.settlements||[],driverIds=[trip.primaryDriverId,trip.secondaryDriverId].filter(Boolean),visibleIds=state.user.role==='admin'?driverIds:[state.user.id];$('#tabContent').innerHTML=`<div class="settlement-intro"><div><small>KONTANTAFSTEMNING</small><h2>Aflevering fra chauffør til kontor</h2><p>Beløbene beregnes fra betalinger modtaget i bussen på denne tur. DKK og EUR afstemmes separat.</p></div><span>${esc(trip.title)}<b>${date(trip.departureAt)}</b></span></div><div class="settlement-drivers">${visibleIds.map(driverId=>settlementDriverCard(driverId,all)).join('')}</div><section class="panel settlement-history"><div class="panel-head"><h2>Afstemningshistorik</h2><small>${all.length} afstemninger</small></div>${all.length?`<div class="table-scroll"><table class="list"><thead><tr><th>Chauffør</th><th>Forventet</th><th>Afleveret</th><th>Difference</th><th>Status</th><th>Behandling</th></tr></thead><tbody>${[...all].reverse().map(settlementRow).join('')}</tbody></table></div>`:'<div class="empty">Ingen kontantafstemninger endnu</div>'}</section>`;wireSettlementTab()}
function settlementCash(driverId){const records=[...state.trip.passengers.map(r=>({record:r,kind:'passenger'})),...state.trip.baggage.map(r=>({record:r,kind:'baggage'}))].filter(item=>item.record.cashHolderUserId===driverId&&item.record.paymentLocation==='bus'&&!item.record.cashHandedOverAt);return{records,DKK:records.filter(i=>(i.record.paymentCurrency||'DKK')==='DKK').reduce((s,i)=>s+Number(i.record.cashAmount||0),0),EUR:records.filter(i=>i.record.paymentCurrency==='EUR').reduce((s,i)=>s+Number(i.record.cashAmount||0),0)}}
function settlementDriverCard(driverId,all){const cash=settlementCash(driverId),pending=all.find(s=>s.driverId===driverId&&s.status==='pending'),canSubmit=(state.user.role==='driver'&&state.user.id===driverId)||state.user.role==='admin';return`<section class="settlement-card"><header><div class="avatar">${esc(tripDriverName(driverId).split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><div><small>Kontanter hos</small><h3>${esc(tripDriverName(driverId))}</h3></div>${pending?'<span class="settlement-status pending">Afventer godkendelse</span>':'<span class="settlement-status open">Ikke afleveret</span>'}</header><div class="expected-cash"><div><span>Forventet DKK</span><strong>${money(cash.DKK,'DKK')}</strong></div><div><span>Forventet EUR</span><strong>${money(cash.EUR,'EUR')}</strong></div><small>${cash.records.length} betalinger</small></div>${pending?`<div class="pending-settlement"><span>Indberettet</span><strong>${money(pending.delivered.DKK,'DKK')} · ${money(pending.delivered.EUR,'EUR')}</strong><small>${date(pending.submittedAt)}</small></div>`:cash.records.length&&canSubmit?`<form class="form settlement-form" data-settlement-form="${driverId}"><label>Afleveret DKK<input name="deliveredDKK" type="number" min="0" step="0.01" value="${cash.DKK}" required></label><label>Afleveret EUR<input name="deliveredEUR" type="number" min="0" step="0.01" value="${cash.EUR}" required></label><label class="wide">Forklaring ved difference<textarea name="note" placeholder="Valgfrit, hvis beløbet stemmer"></textarea></label><button class="primary wide">Indsend til godkendelse</button></form>`:'<div class="settlement-empty">Ingen uafstemte kontanter</div>'}</section>`}
function settlementRow(s){const diffDkk=Number(s.difference.DKK),diffEur=Number(s.difference.EUR);return`<tr><td><strong>${esc(s.driverName)}</strong><br><small>${date(s.submittedAt)}</small></td><td>${money(s.expected.DKK,'DKK')}<br>${money(s.expected.EUR,'EUR')}</td><td>${money(s.delivered.DKK,'DKK')}<br>${money(s.delivered.EUR,'EUR')}</td><td class="${diffDkk||diffEur?'difference':'balanced'}">${money(diffDkk,'DKK')}<br>${money(diffEur,'EUR')}</td><td><span class="settlement-status ${s.status}">${s.status==='pending'?'Afventer':s.status==='approved'?'Godkendt':'Afvist'}</span></td><td>${state.user.role==='admin'&&s.status==='pending'?`<div class="review-actions"><button class="mini done" data-approve-settlement="${s.id}">Godkend</button><button class="mini danger" data-reject-settlement="${s.id}">Afvis</button></div>`:`<small>${s.reviewedByName?`${esc(s.reviewedByName)}<br>${date(s.reviewedAt)}`:'–'}</small>`}</td></tr>`}
function wireSettlementTab(){$$('[data-settlement-form]').forEach(form=>form.onsubmit=async event=>{event.preventDefault();const payload={driverId:Number(form.dataset.settlementForm),...Object.fromEntries(new FormData(form))};try{const settlement=await api(`/api/trips/${state.trip.trip.id}/settlements`,{method:'POST',body:JSON.stringify(payload)});state.trip.settlements.push(settlement);toast('Afstemningen er sendt til administratoren');renderTrip()}catch(error){toast(error.message)}});$$('[data-approve-settlement]').forEach(button=>button.onclick=()=>reviewSettlement(Number(button.dataset.approveSettlement),'approved'));$$('[data-reject-settlement]').forEach(button=>button.onclick=()=>reviewSettlement(Number(button.dataset.rejectSettlement),'rejected'))}
async function reviewSettlement(id,status){const reviewNote=status==='rejected'?prompt('Hvorfor afvises afstemningen?')||'Afvist af administrator':'';try{await api(`/api/trips/${state.trip.trip.id}/settlements`,{method:'PATCH',body:JSON.stringify({id,status,reviewNote})});state.trip=await api(`/api/trips/${state.trip.trip.id}`);toast(status==='approved'?'Afstemningen er godkendt. Pengene står nu på kontoret.':'Afstemningen er afvist');renderTrip()}catch(error){toast(error.message)}}

const passengerDetailBeforeSettlement=showPassengerDetail;showPassengerDetail=function(id){passengerDetailBeforeSettlement(id);const passenger=state.trip.passengers.find(p=>p.id===id);if(passenger?.cashHandedOverAt){const row=[...$$('.detail-list>div')].find(div=>div.querySelector('span')?.textContent==='Pengene står hos');if(row)row.querySelector('strong').textContent=`Kontoret · afleveret ${date(passenger.cashHandedOverAt)}`}};

const reportsBeforeOfficeCash=renderReports;renderReports=async function(){await reportsBeforeOfficeCash();if(!$('.nav[data-view="reports"]')?.classList.contains('active'))return;try{const report=await api('/api/reports');$('.finance-grid')?.insertAdjacentHTML('afterend',`<div class="office-cash"><div><span>Godkendt og afleveret til kontoret · DKK</span><strong>${money(report.summary.cashAtOffice.DKK,'DKK')}</strong></div><div><span>Godkendt og afleveret til kontoret · EUR</span><strong>${money(report.summary.cashAtOffice.EUR,'EUR')}</strong></div></div>`)}catch(error){toast(error.message)}};

const seatGridBeforeSetraPlan=seatGrid;
seatGrid=function(selectable=true){const isDouble=state.trip.trip.bus?.type==='double'||state.trip.trip.seatCount===84||state.trip.seats.length===84;if(!isDouble)return seatGridBeforeSetraPlan(selectable);const lower=state.trip.seats.filter(seat=>seat.deck==='lower').slice(0,22),upper=state.trip.seats.filter(seat=>seat.deck==='upper');if(!upper.length){const all=[...state.trip.seats];lower.splice(0,lower.length,...all.slice(0,22));upper.push(...all.slice(22,84))}return`<div class="setra-plan-heading"><div><small>DOBBELTDÆKKER · 84 SÆDER</small><h3>Vælg sæde på plantegningen</h3></div><div><span>↑ Overetage 62</span><span>↓ Underetage 22</span></div></div><div class="setra-decks">${renderSetraUpper(upper,selectable)}${renderSetraLower(lower,selectable)}</div><div class="legend setra-legend"><span><i class="dot"></i>Ledigt</span><span><i class="dot front"></i>Front +100 kr.</span><span><i class="dot table"></i>Bord +75 kr.</span><span><i class="dot occupied"></i>Optaget</span><span class="direction-key">↑ Bussens front</span></div>`};
function renderSetraUpper(seats,selectable){return`<section class="setra-deck upper"><header><span>2</span><div><small>ØVERSTE ETAGE</small><strong>Overetage · 62 sæder</strong></div></header><div class="setra-bus-shell"><div class="setra-windshield">PANORAMAFRONT</div><div class="upper-front"><div class="facility stairs">Trappe</div><div class="facility screen">Skærm</div></div><div class="setra-seat-rows">${referenceSeatRows(seats,selectable)}</div><div class="upper-rear"><div class="facility stairs">Trappe</div><div class="facility emergency">Nødudgang</div></div><div class="setra-rear">BAG</div></div></section>`}
function renderSetraLower(seats,selectable){const tableSeats=seats.slice(0,8),regular=seats.slice(8);return`<section class="setra-deck lower"><header><span>1</span><div><small>NEDERSTE ETAGE</small><strong>Underetage · 22 sæder</strong></div></header><div class="setra-bus-shell"><div class="setra-windshield">FRONT</div><div class="cockpit-row"><div class="facility driver">Fører</div><div class="facility entrance">Indgang</div><div class="facility stairs">Trappe</div></div><div class="service-row"><div class="facility kitchen">Minikøkken</div><div class="facility wc">WC</div></div><div class="table-zone"><div class="table-zone-title">2 BORDGRUPPER · 8 BORDPLADSER</div>${Array.from({length:2},(_,index)=>renderTableBay(tableSeats.slice(index*4,index*4+4),selectable,index+1)).join('')}</div><div class="setra-seat-rows lower-rear-seats">${referenceSeatRows(regular,selectable)}</div><div class="facility rear-stairs">Trappe til overetage</div><div class="setra-rear">BAG</div></div></section>`}
function renderTableBay(seats,selectable,index){return`<div class="table-bay"><small>Bord ${index}</small><div class="facing-pair top">${seats.slice(0,2).map(seat=>seatButton(seat,selectable)).join('')}</div><div class="table-symbol">BORD</div><div class="facing-pair bottom">${seats.slice(2,4).map(seat=>seatButton(seat,selectable)).join('')}</div></div>`}
function referenceSeatRows(seats,selectable){let html='';for(let i=0;i<seats.length;i+=4){const row=seats.slice(i,i+4);html+=`<div class="reference-seat-row"><div>${row.slice(0,2).map(seat=>seatButton(seat,selectable)).join('')}</div><span>↕</span><div>${row.slice(2,4).map(seat=>seatButton(seat,selectable)).join('')}</div></div>`}return html}

const tripRendererBeforeBusAssignment=renderTrip;renderTrip=function(){tripRendererBeforeBusAssignment();if(state.user.role!=='admin'||!state.trip?.trip||!(state.buses||[]).length)return;const trip=state.trip.trip;$('.detail-hero').insertAdjacentHTML('afterend',`<form class="trip-bus-assignment" id="tripBusAssignment"><label>Bus på denne tur<select name="busId">${state.buses.map(bus=>`<option value="${bus.id}" ${trip.busId===bus.id?'selected':''}>${esc(bus.name)} · ${esc(bus.registration)} · ${bus.type==='double'?'Dobbeltdækker 22/62':'Almindelig '+bus.seatCount}</option>`).join('')}</select></label><button class="mini">${trip.busId?'Skift bus':'Tilknyt bus'}</button><small>Dobbeltdækker aktiverer automatisk den nye 84-sæders plantegning.</small></form>`);$('#tripBusAssignment').onsubmit=async event=>{event.preventDefault();try{const updated=await api(`/api/trips/${trip.id}`,{method:'PATCH',body:JSON.stringify({busId:Number(event.target.busId.value)})});state.trip.trip=updated;state.trip.seats=await api(`/api/trips/${trip.id}/seats`);const overview=state.trips.find(t=>t.id===trip.id);if(overview)Object.assign(overview,updated);toast('Bussen og sædeplanen er opdateret');renderTrip()}catch(error){toast(error.message)}}};
